// 1. Configuration Validation
if (!isfinite(mh_config.minimum_span) || mh_config.minimum_span <= 0.0) {
    mh_output.mode = MH_FAULT;
    return;
}
if (mh_config.required < 4 || mh_config.required > 100) {
    mh_output.mode = MH_FAULT;
    return;
}
if (!isfinite(mh_config.max_rejected_windows) || mh_config.max_rejected_windows > 1000) {
    mh_output.mode = MH_FAULT;
    return;
}

// 2. Disable Handling
if (!mh_input.enable) {
    mh_state.mode = MH_IDLE;
    mh_state.count = 0;
    mh_state.rejected = 0;
    mh_output.mode = MH_IDLE;
    return;
}

// 3. Input Sample Validation
if (mh_input.sample == NULL || !adcs_is_finite_vec3(&mh_input.sample->value)) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    return;
}

// 4. State Machine Logic
if (mh_state.mode == MH_IDLE) {
    mh_state.mode = MH_COLLECT;
    mh_state.count = 0;
    mh_state.rejected = 0;
    // Fall through to collect logic
}

if (mh_state.mode == MH_READY) {
    // Calibration complete, ignore new samples or maintain state
    // Output remains READY
    return;
}

if (mh_state.mode == MH_COLLECT) {
    const adcs_vec3_t *v = &mh_input.sample->value;

    if (mh_state.count == 0) {
        mh_state.minimum = *v;
        mh_state.maximum = *v;
    } else {
        if (v->x < mh_state.minimum.x) mh_state.minimum.x = v->x;
        if (v->y < mh_state.minimum.y) mh_state.minimum.y = v->y;
        if (v->z < mh_state.minimum.z) mh_state.minimum.z = v->z;

        if (v->x > mh_state.maximum.x) mh_state.maximum.x = v->x;
        if (v->y > mh_state.maximum.y) mh_state.maximum.y = v->y;
        if (v->z > mh_state.maximum.z) mh_state.maximum.z = v->z;
    }

    mh_state.count++;

    if (mh_state.count < mh_config.required) {
        mh_output.mode = MH_COLLECT;
        return;
    }
}

// Window Complete Calculation
adcs_vec3_t bias = {0};
adcs_vec3_t half_span = {0};

bias.x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
bias.y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
bias.z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;

half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

int all_sufficient = 1;
if (half_span.x < mh_config.minimum_span) all_sufficient = 0;
if (half_span.y < mh_config.minimum_span) all_sufficient = 0;
if (half_span.z < mh_config.minimum_span) all_sufficient = 0;

if (all_sufficient) {
    mh_state.mode = MH_READY;
    mh_state.bias = bias;
    mh_state.rejected = 0; // Reset rejection counter on success

    double norm_sq = half_span.x * half_span.x + half_span.y * half_span.y + half_span.z * half_span.z;

    mh_output.mode = MH_READY;
    mh_output.bias = bias;
    mh_output.half_span = half_span;
    mh_output.span_norm = sqrt(norm_sq);
    mh_output.span_energy = norm_sq;
} else {
    // Restart collection
    mh_state.count = 0;
    mh_state.minimum = (adcs_vec3_t){0};
    mh_state.maximum = (adcs_vec3_t){0};

    if (mh_config.max_rejected_windows == 0) {
        // Unlimited rejections allowed
        mh_state.mode = MH_COLLECT;
        mh_output.mode = MH_COLLECT;
    } else {
        if (mh_state.rejected >= mh_config.max_rejected_windows) {
            mh_state.mode = MH_FAULT;
            mh_output.mode = MH_FAULT;
        } else {
            mh_state.rejected++;
            mh_state.mode = MH_COLLECT;
            mh_output.mode = MH_COLLECT;
        }
    }
}

