    // 1. Validate Inputs and Configuration
    if (mh_input.sample == NULL || !adcs_is_finite_vec3(mh_input.sample)) {
        mh_state.mode = MH_FAULT;
        goto update_output;
    }

    if (!isfinite(mh_config.required) || mh_config.required < 4 || mh_config.required > 100 ||
        !isfinite(mh_config.minimum_span) || mh_config.minimum_span <= 0.0 ||
        !isfinite(mh_config.max_rejected_windows) || mh_config.max_rejected_windows > 1000) {
        mh_state.mode = MH_FAULT;
        goto update_output;
    }

    // 2. Handle Disable
    if (!mh_input.enable) {
        mh_state.mode = MH_IDLE;
        mh_state.count = 0;
        mh_state.rejected = 0;
        mh_state.bias.x = 0.0; mh_state.bias.y = 0.0; mh_state.bias.z = 0.0;
        mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
        mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
        goto update_output;
    }

    // 3. State Machine Processing
    switch (mh_state.mode) {
        case MH_READY:
            // Stay in READY, output current valid state. Do not consume new samples.
            break;

        case MH_FAULT:
            // Stay in FAULT.
            break;

        case MH_IDLE:
        case MH_COLLECT:
            // Initialize or Continue Collection
            if (mh_state.mode == MH_IDLE || mh_state.count == 0) {
                mh_state.mode = MH_COLLECT;
                mh_state.minimum = *mh_input.sample;
                mh_state.maximum = *mh_input.sample;
            }

            // Update Extrema
            if (mh_input.sample->x < mh_state.minimum.x) mh_state.minimum.x = mh_input.sample->x;
            if (mh_input.sample->y < mh_state.minimum.y) mh_state.minimum.y = mh_input.sample->y;
            if (mh_input.sample->z < mh_state.minimum.z) mh_state.minimum.z = mh_input.sample->z;

            if (mh_input.sample->x > mh_state.maximum.x) mh_state.maximum.x = mh_input.sample->x;
            if (mh_input.sample->y > mh_state.maximum.y) mh_state.maximum.y = mh_input.sample->y;
            if (mh_input.sample->z > mh_state.maximum.z) mh_state.maximum.z = mh_input.sample->z;

            mh_state.count++;

            // Check if window is complete
            if (mh_state.count >= mh_config.required) {
                double bias_x = (mh_state.maximum.x + mh_state.minimum.x) * 0.5;
                double bias_y = (mh_state.maximum.y + mh_state.minimum.y) * 0.5;
                double bias_z = (mh_state.maximum.z + mh_state.minimum.z) * 0.5;

                double hs_x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
                double hs_y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
                double hs_z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

                adcs_vec3_t half_span = {hs_x, hs_y, hs_z};
                double span_norm = adcs_vec3_norm(&half_span);
                double span_energy = adcs_vec3_dot(&half_span, &half_span);

                // Check if ALL components meet minimum_span requirement
                int valid = (fabs(hs_x) >= mh_config.minimum_span) &&
                            (fabs(hs_y) >= mh_config.minimum_span) &&
                            (fabs(hs_z) >= mh_config.minimum_span);

                if (valid) {
                    mh_state.bias.x = bias_x;
                    mh_state.bias.y = bias_y;
                    mh_state.bias.z = bias_z;

                    mh_output.bias = mh_state.bias;
                    mh_output.half_span = half_span;
                    mh_output.span_norm = span_norm;
                    mh_output.span_energy = span_energy;
                    mh_output.mode = MH_READY;
                    mh_output.count = mh_state.count;
                    mh_output.rejected = mh_state.rejected;

                    mh_state.mode = MH_READY;
                } else {
                    // Insufficient excitation
                    mh_state.rejected++;

                    // Prepare output for the failed window (as per "publish..." requirement)
                    mh_output.bias.x = bias_x;
                    mh_output.bias.y = bias_y;
                    mh_output.bias.z = bias_z;
                    mh_output.half_span = half_span;
                    mh_output.span_norm = span_norm;
                    mh_output.span_energy = span_energy;
                    mh_output.count = mh_state.count;
                    mh_output.rejected = mh_state.rejected;

                    // Determine next state
                    if (mh_config.max_rejected_windows == 0 || 
                        mh_state.rejected < mh_config.max_rejected_windows) {
                        // Restart collection
                        mh_state.mode = MH_COLLECT;
                        mh_state.count = 0;
                        mh_state.minimum = *mh_input.sample;
                        mh_state.maximum = *mh_input.sample;
                        mh_output.mode = MH_COLLECT;
                    } else {
                        // Latch Fault
                        mh_state.mode = MH_FAULT;
                        mh_output.mode = MH_FAULT;
                    }
                }
            } else {
                // Window not complete yet
                mh_output.mode = mh_state.mode;
                mh_output.count = mh_state.count;
                mh_output.rejected = mh_state.rejected;
                // Vectors remain uninitialized/zeros until window completes
                mh_output.bias = (adcs_vec3_t){0,0,0};
                mh_output.half_span = (adcs_vec3_t){0,0,0};
                mh_output.span_norm = 0.0;
                mh_output.span_energy = 0.0;
            }
            break;
    }

