    (!isfinite(mh_config.minimum_span)) || (mh_config.minimum_span <= 0.0) ||
    (mh_config.max_rejected_windows > 1000)) {
    mh_state.mode = MH_FAULT;
    mh_state.count = 0;
    mh_state.rejected = 0;
    mh_output.mode = MH_FAULT;
    mh_output.count = 0;
    mh_output.rejected = 0;
    mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
    mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

// 4. Existing Fault State Handling
if (mh_state.mode == MH_FAULT) {
    mh_output.mode = MH_FAULT;
    mh_output.count = 0;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
    mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

// 5. Existing Ready State Handling
if (mh_state.mode == MH_READY) {
    mh_output.mode = MH_READY;
    mh_output.count = 0;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias.x = (mh_state.maximum.x + mh_state.minimum.x) * 0.5;
    mh_output.bias.y = (mh_state.maximum.y + mh_state.minimum.y) * 0.5;
    mh_output.bias.z = (mh_state.maximum.z + mh_state.minimum.z) * 0.5;
    mh_output.half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
    mh_output.half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
    mh_output.half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;
    mh_output.span_norm = sqrt(mh_output.half_span.x*mh_output.half_span.x + 
                               mh_output.half_span.y*mh_output.half_span.y + 
                               mh_output.half_span.z*mh_output.half_span.z);
    mh_output.span_energy = mh_output.span_norm * mh_output.span_norm;
    return;
}

// 6. Data Collection (COLLECT or IDLE start)
const adcs_vec3_t *samp = mh_input.sample;

// Update min/max for each component
if (mh_state.count == 0) {
    mh_state.minimum.x = samp->x; mh_state.maximum.x = samp->x;
    mh_state.minimum.y = samp->y; mh_state.maximum.y = samp->y;
    mh_state.minimum.z = samp->z; mh_state.maximum.z = samp->z;
} else {
    if (samp->x < mh_state.minimum.x) mh_state.minimum.x = samp->x;
    if (samp->x > mh_state.maximum.x) mh_state.maximum.x = samp->x;
    if (samp->y < mh_state.minimum.y) mh_state.minimum.y = samp->y;
    if (samp->y > mh_state.maximum.y) mh_state.maximum.y = samp->y;
    if (samp->z < mh_state.minimum.z) mh_state.minimum.z = samp->z;
    if (samp->z > mh_state.maximum.z) mh_state.maximum.z = samp->z;
}

mh_state.count++;

// 7. Window Completion Check
if (mh_state.count < mh_config.required) {
    mh_output.mode = MH_COLLECT;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
    mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

// 8. Sufficiency Check
double hs_x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
double hs_y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
double hs_z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

int all_sufficient = 1;
if (fabs(hs_x) < mh_config.minimum_span) all_sufficient = 0;
if (fabs(hs_y) < mh_config.minimum_span) all_sufficient = 0;
if (fabs(hs_z) < mh_config.minimum_span) all_sufficient = 0;

if (all_sufficient) {
    // 9. Successful Calibration
    mh_output.bias.x = (mh_state.maximum.x + mh_state.minimum.x) * 0.5;
    mh_output.bias.y = (mh_state.maximum.y + mh_state.minimum.y) * 0.5;
    mh_output.bias.z = (mh_state.maximum.z + mh_state.minimum.z) * 0.5;

    mh_output.half_span.x = hs_x;
    mh_output.half_span.y = hs_y;
    mh_output.half_span.z = hs_z;

    mh_output.span_norm = sqrt(hs_x*hs_x + hs_y*hs_y + hs_z*hs_z);
    mh_output.span_energy = mh_output.span_norm * mh_output.span_norm;

    mh_state.mode = MH_READY;
    mh_state.count = 0;
    mh_state.rejected = 0;

    mh_output.mode = MH_READY;
    mh_output.count = 0;
    mh_output.rejected = 0;
    return;
} else {
    // 10. Insufficient Excitation
    mh_state.rejected++;
    mh_state.count = 0; 

    if ((mh_config.max_rejected_windows != 0) && 
        (mh_state.rejected > mh_config.max_rejected_windows)) {
        mh_state.mode = MH_FAULT;
        mh_output.mode = MH_FAULT;
        mh_output.count = 0;
        mh_output.rejected = mh_state.rejected;
        mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
        mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
        mh_output.span_norm = 0.0;
        mh_output.span_energy = 0.0;
        return;
    }

    mh_output.mode = MH_COLLECT;
    mh_output.count = 0;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
    mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}
